#include "SmpBringup.hpp"
namespace Davis::SmpBringup {
bool BringUpApplicationProcessors(SmpTopology::State&t,SmpRuntime::State&r,ApBootstrap::State&b,ApRendezvous::Mailbox&m,u64 tramp,u64 cr3,const LapicIpi::Transport&lapic,const Platform&p,Result&out){out={};if(!t.ready||!r.ready||!b.ready||!m.ready||!p.installLowMemory||!p.poll||!p.pollLimit||!ApStartup::ValidateTrampoline(tramp)||(cr3&0xfffull)||!cr3)return false;for(u32 i=0;i<b.count;i++){auto*c=(ApBootstrap::CpuBoot*)&b.cpu[i];if(c->stage==ApBootstrap::Stage::Online)continue;out.attempted++;ApTrampoline::Handoff h{};if(!ApTrampoline::Build(h,c->apicId,c->logicalId,cr3,c->stackTop,c->entryPoint,c->token,b.generation)){out.failed++;continue;}ApLowMemory::Image image{};if(!ApLowMemory::Build(image,tramp,h)||!p.installLowMemory(p.context,tramp,image.bytes,ApLowMemory::ImageBytes)){out.failed++;continue;}if(!ApBootstrap::StartupSent(b,t,c->apicId)){out.failed++;continue;}ApStartup::Plan plan{};LapicIpi::Stats stats{};if(!ApStartup::BuildPlan(c->apicId,tramp,plan)||!LapicIpi::ExecutePlan(lapic,plan,stats)){ApBootstrap::MarkFailed(b,t,c->apicId);out.failed++;continue;}out.ipis+=stats.sent;if(!p.poll(p.context,c->apicId,c->token,h.generation,p.pollLimit)){ApBootstrap::MarkFailed(b,t,c->apicId);out.failed++;continue;}if(!ApRendezvous::Observe(m,c->logicalId,c->apicId,c->token,h.generation,ApRendezvous::Stage::Rendezvous)||!ApBootstrap::EnteredLongMode(b,c->apicId,c->token)||!ApBootstrap::Rendezvous(b,c->apicId,c->token)||!ApBootstrap::MarkOnline(b,t,r,c->apicId,c->token)){out.failed++;continue;}ApRendezvous::Publish(m,c->logicalId,c->apicId,c->token,h.generation,ApRendezvous::Stage::Online);out.online++;}return out.online+out.failed==out.attempted;}
}
